"<script>(function(){function el(i){return document.getElementById(i)}var lock=null;function err(t){el('error').innerHTML=t||''}function xhr(m,u,cb){var x=new XMLHttpRequest();x.open(m,u,true);x.onreadystatechange=function(){if(x.readyState===4){if(x.status>=200&&x.status<300){try{cb(null,JSON.parse(x.responseText))}catch(e){cb('JSON '+e.message,null)}}else cb('HTTP '+x.status,null)}};x.send(null)}function renderLock(d){lock=d;el('lockService').innerHTML='ONLINE';el('lockPid').innerHTML=String(d.pid||'?');el('lockPill').innerHTML='LOCK ONLINE';el('lockPill').className='pill on';el('jobState').innerHTML=d.job_running?((d.job_kind===2?'ATIVANDO':'VERIFICANDO')+'...'):(d.job_done?'FINALIZADO':'PARADO');el('jobPid').innerHTML=d.job_running?String(d.job_pid):'-';el('log').innerHTML=d.log||'[LOCK] sem log';if(d.account_valid){el('accName').innerHTML=d.account_name||'-';el('accUser').innerHTML=String(d.account_user)+' / '+String(d.account_slot);el('accId').innerHTML=d.account_id_hex||'-';el('accStatus').innerHTML=d.account_activated?'ATIVADA':'OFFLINE NÃO ATIVADA';el('activate').disabled=d.account_activated||d.job_running;el('pair').disabled=!d.account_activated;el('badge').innerHTML=d.account_activated?'CONTA ATIVADA':'CONTA OFFLINE NÃO ATIVADA';el('badge').className=d.account_activated?'badge ok':'badge';el('screenTitle').innerHTML=d.account_activated?'Conta pronta':'Conta offline detectada';el('screenText').innerHTML=d.account_activated?'Agora o Astro Remote pode gerar o PIN.':'Confira o usuário e ative pelo Astro Lock.'}else{el('activate').disabled=true;el('pair').disabled=true}el('check').disabled=d.job_running}function lockStatus(){xhr('GET','/service/lock/_root/status',function(e,d){if(e){el('lockService').innerHTML='OFFLINE';el('lockPill').innerHTML='LOCK OFF';err('Astro Lock: '+e);return}renderLock(d)})}function remoteStatus(){xhr('GET','/service/remote/_root/status',function(e,w){if(e){err('Astro Remote: '+e);return}el('worker').innerHTML='astrorem PID '+String(w.pid||'?');el('rpEnabled').innerHTML=w.remoteplay_enabled?'HABILITADO':'DESATIVADO';el('rpPort').innerHTML=w.remoteplay_tcp_9295?'RESPONDENDO':'SEM RESPOSTA';el('pairing').innerHTML=w.pairing_complete?'CONCLUÍDO':(w.pairing_active?'AGUARDANDO DISPOSITIVO':'PARADO');el('remotePill').innerHTML='REMOTE ONLINE';el('remotePill').className='pill on';el('phasePill').innerHTML=String(w.phase||'idle').toUpperCase();if(w.pairing_pin_ready){var s=String(w.pairing_pin);while(s.length<8)s='0'+s;el('pin').innerHTML=s.substring(0,4)+' '+s.substring(4);el('account').innerHTML='Account ID: '+(w.pairing_account_id||'');el('timer').innerHTML='Tempo restante: '+String(w.pairing_seconds_left||0)+'s'}})}function post(u,cb){xhr('POST',u,function(e,d){if(e){err(e);return}if(cb)cb(d)})}el('check').onclick=function(){err('');post('/service/lock/_root/check',renderLock)};el('activate').onclick=function(){if(!lock||!lock.account_valid||lock.account_activated)return;var m='Ativar esta conta com Astro Lock?\n\nNome: '+(lock.account_name||'-')+'\nUID: '+lock.account_user+'\nSlot: '+lock.account_slot+'\nAccount ID proposto: '+(lock.account_proposed_id_hex||'-')+'\n\nO log ficará visível durante todo o processo.';if(confirm(m)){post('/service/lock/_root/activate',renderLock)}};el('pair').onclick=function(){post('/service/remote/_root/pairing/prepare',function(){remoteStatus()})};el('cancel').onclick=function(){post('/service/remote/_root/pairing/cancel',function(){remoteStatus()})};lockStatus();remoteStatus();setInterval(function(){lockStatus();remoteStatus()},1000)})();</script></body></html>";

